  x1 = Math.floor((b.x + b.w - 1e-3) / 36);
  y0 = Math.floor(b.y / 36);
  y1 = Math.floor((b.y + b.h - 1e-3) / 36);
  c.onGround = false;
  for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
    if (solidAt(tx, ty)) {
      if (c.vy > 0) {
        c.y = ty * 36 - 0.01;
        c.onGround = true;
      } else if (c.vy < 0) c.y = (ty + 1) * 36 + 30 + 0.01;
      c.vy = 0;
      b = boxOf(c);
      y0 = Math.floor(b.y / 36);
      y1 = Math.floor((b.y + b.h - 1e-3) / 36);
    }
  }
  c.standing = null;
